from __future__ import annotations

import sys
from pathlib import Path

SUITE_LIB = Path(__file__).resolve().parents[1] / "_lib"
if str(SUITE_LIB) not in sys.path:
    sys.path.insert(0, str(SUITE_LIB))

from autoresearch_suite import runtime  # noqa: E402
from autoresearch_suite import software_pymod  # noqa: E402

DIRECTION = "maximize"
TIMEOUT = 420
P = {'subject': 'fractions', 'cpu_seconds': 60, 'max_tests': 30}


def task(module):
    score, details = software_pymod.mutation_score(module, P['subject'], cpu_seconds=P['cpu_seconds'], max_tests=P['max_tests'])
    return runtime.success(score, 'maximize', **details)


def evaluate(program_path="initial_program.py"):
    result = runtime.run(program_path, task, timeout=TIMEOUT)
    result["direction"] = DIRECTION
    return result


if __name__ == "__main__":
    sys.exit(runtime.main(evaluate))
